  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	
  9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 10	public final class ReservationService {
 11	
 12	    static final String HOTEL_NAME = "Pousada Maré Alta";
 13	    static final String SIGNATURE = """
 14	            --
 15	            Pousada Maré Alta
 16	            (79) 3200-0000 | @pousadamarealta""";
 17	
 18	    private final Rooms rooms;
 19	    private final ReservationStore store;
 20	    private final PriceCalculator priceCalculator;
 21	    private final EmailSender emailSender;
 22	
 23	    public ReservationService(
 24	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 25	        this.rooms = rooms;
 26	        this.store = store;
 27	        this.priceCalculator = priceCalculator;
 28	        this.emailSender = emailSender;
 29	    }
 30	
 31	    public synchronized Reservation create(NewReservation request) {
 32	        if (!request.checkOut().isAfter(request.checkIn())) {
 33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 34	        }
 35	        if (request.guests() < 1) {
 36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 37	        }
 38	        Room room = rooms.find(request.roomNumber())
 39	                .orElseThrow(() -> new HotelException(
 40	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 41	        if (request.guests() > room.capacity()) {
 42	            throw new HotelException(
 43	                    ErrorCode.CAPACITY_EXCEEDED,
 44	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 45	        }
 46	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 47	            throw new HotelException(
 48	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 49	        }
 50	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 51	        return store.add(request, price);
 52	    }
 53	
 54	    public Reservation find(long reservationId) {
 55	        return store.find(reservationId)
 56	                .orElseThrow(() -> new HotelException(
 57	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 58	    }
 59	
 60	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 61	    public synchronized Reservation confirm(long reservationId) {
 62	        Reservation reservation = find(reservationId);
 63	        if (reservation.status() != ReservationStatus.PENDING) {
 64	            throw notAllowed(reservation, "confirm");
 65	        }
 66	        reservation.confirmPayment();
 67	        store.update(reservation);
 68	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 69	        emailSender.send(
 70	                reservation.guest().email(),
 71	                "Reserva confirmada - " + HOTEL_NAME,
 72	                confirmationEmailBody(reservation, receipt));
 73	        return reservation;
 74	    }
 75	
 76	    /**
 77	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 78	     * reservation was never paid, so nothing comes back).
 79	     */
 80	    public synchronized Reservation cancel(long reservationId) {
 81	        Reservation reservation = find(reservationId);
 82	        if (reservation.status() != ReservationStatus.PENDING
 83	                && reservation.status() != ReservationStatus.CONFIRMED) {
 84	            throw notAllowed(reservation, "cancel");
 85	        }
 86	        BigDecimal refund = switch (reservation.ratePlan()) {
 87	            case STANDARD -> reservation.amountPaid();
 88	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 89	        };
 90	        reservation.cancel(refund);
 91	        store.update(reservation);
 92	        return reservation;
 93	    }
 94	
 95	    public synchronized Reservation checkIn(long reservationId) {
 96	        Reservation reservation = find(reservationId);
 97	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 98	            throw notAllowed(reservation, "check in");
 99	        }
100	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
101	        store.update(reservation);
102	        return reservation;
103	    }
104	
105	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
106	    public synchronized ReservationReceipt checkOut(long reservationId) {
107	        Reservation reservation = find(reservationId);
108	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
109	            throw notAllowed(reservation, "check out");
110	        }
111	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
112	        store.update(reservation);
113	        return new ReservationReceipt(reservation, roomOf(reservation));
114	    }
115	
116	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
117	    public ReservationReceipt receiptCopy(long reservationId) {
118	        Reservation reservation = find(reservationId);
119	        if (!reservation.isPaid()) {
120	            throw notAllowed(reservation, "issue a receipt for");
121	        }
122	        return new ReservationReceipt(reservation, roomOf(reservation));
123	    }
124	
125	    private Room roomOf(Reservation reservation) {
126	        return rooms.find(reservation.roomNumber()).orElseThrow();
127	    }
128	
129	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
130	        return "Olá, " + reservation.guest().name() + "!\n\n"
131	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
132	                + receipt.text() + "\n"
133	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
134	                + "Até breve!\n\n"
135	                + SIGNATURE;
136	    }
137	
138	    private static HotelException notAllowed(Reservation reservation, String operation) {
139	        return new HotelException(
140	                ErrorCode.OPERATION_NOT_ALLOWED,
141	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
142	    }
143	}
